[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$ip=Get-NetIPAddress -IPAddress '172.16.105.70';$a=Get-NetAdapter -InterfaceIndex $ip.InterfaceIndex;[pscustomobject]@{adapter=@($a|Select-Object Name,InterfaceDescription,ifIndex,Status,LinkSpeed,DriverInformation,DriverVersion,DriverDate);rss=@(Get-NetAdapterRss -Name $a.Name -ErrorAction SilentlyContinue|Select-Object Name,Enabled,NumberOfReceiveQueues,Profile,BaseProcessorGroup,BaseProcessorNumber,MaxProcessorGroup,MaxProcessorNumber,MaxProcessors,RssProcessorArray,IndirectionTable);rsc=@(Get-NetAdapterRsc -Name $a.Name -ErrorAction SilentlyContinue|Select-Object Name,IPv4Enabled,IPv6Enabled,IPv4OperationalState,IPv6OperationalState);advanced=@(Get-NetAdapterAdvancedProperty -Name $a.Name|Select-Object DisplayName,DisplayValue,RegistryKeyword,RegistryValue);cpu=@(Get-CimInstance Win32_Processor|Select-Object Name,NumberOfCores,NumberOfLogicalProcessors);os=@(Get-CimInstance Win32_OperatingSystem|Select-Object Version,BuildNumber);esrv=@(Get-Process esrv_svc -ErrorAction SilentlyContinue|Select-Object Id,PriorityClass,ProcessorAffinity,CPU)}|ConvertTo-Json -Depth 7